@startuml

class Employee {
  + name : string
  + ssn : int
}

abstract class CreativeEmployee {
  + hasOscar : boolean
}

class Actor {
  + education : string
}

class Director {
  + assistantName : string
}

class Technician {
  + fieldOfActivity : string
}

class FilmSet {
  + location : string
}

class Film {
  + title : string
  + releaseYear : int
}

enum Genre {
  Thriller
  Action
  Horror
  Comedy
}

class Screenwriter {
  + name : string
  + mostSuccessfulFilm : string
}

class Screenplay {
  + title : string
  + version : string
  + date : date
  + numberOfScenes : int
  + plot : string
}

class Novel {
  + title : string
  + author : string
}

class Concept {}

CreativeEmployee --|> Employee
Actor --|> CreativeEmployee
Director --|> CreativeEmployee
Technician --|> Employee

FilmSet "*" -- "*" Film
Film "*" -- "1" Genre

Screenwriter "1" -- "*" Screenplay
Screenplay "*" -- "1" Film

Screenplay --|> Novel : based on
Screenplay --|> Concept : based on

Actor "1..*" -- "1" Screenplay : reads
Director "1" -- "1" Screenplay : implements

@enduml

